import{_ as o}from"./chunks/02.7bSgNsEh.js";import{_ as n,o as s,c as r,j as a,a as t,aa as i}from"./chunks/framework.BAs_AphD.js";const d="/buildary-help-preview/media/cs/diary/archivace.png",z=JSON.parse('{"title":"Ukončit stavbu","description":"","frontmatter":{"title":"Ukončit stavbu","wiki":"cs:diary:projectended"},"headers":[],"relativePath":"diary/projectended.md","filePath":"diary/projectended.md","lastUpdated":1794209661000}'),v={name:"diary/projectended.md"};function l(u,e,c,k,p,b){return s(),r("div",null,[...e[0]||(e[0]=[a("h1",{id:"ukoncit-stavbu",tabindex:"-1"},[t("Ukončit stavbu "),a("a",{class:"header-anchor",href:"#ukoncit-stavbu","aria-label":'Permalink to "Ukončit stavbu"'},"​")],-1),a("p",null,"Po dokončení stavbu ukončete v Nastavení stavby. Ukončená stavba je jen pro čtení a zároveň tím skončí její běžná fakturace. Při ukončení se rozhodnete, zda stavbu archivovat, nebo dát ke smazání – volbu už nejde vrátit.",-1),a("p",null,[t("Krok za krokem: "),a("a",{href:"/buildary-help-preview/akademie/ukonceni-stavby"},"Ukončit stavbu"),t(" v Akademii.")],-1),a("div",{class:"video"},[a("iframe",{src:"https://www.youtube-nocookie.com/embed/eIgMK7-1jl0",title:"Video: Ukončení stavby",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),i('<h2 id="ukoncit-stavbu-1" tabindex="-1">Ukončit stavbu <a class="header-anchor" href="#ukoncit-stavbu-1" aria-label="Permalink to &quot;Ukončit stavbu&quot;">​</a></h2><ol><li>Otevřete <strong>Nastavení stavby</strong> (ikona ozubeného kola v levém panelu).</li><li>Na záložce <strong>Stavba</strong> klikněte vpravo nahoře na <strong>Ukončit stavbu</strong>.</li><li>V okně <strong>Archivovat nebo smazat</strong> zvolte <strong>Archivovat</strong>, nebo <strong>Ke smazání</strong>. Pokud si to rozmyslíte, okno zavřete tlačítkem <strong>Zavřít</strong> – stavba zůstane beze změny.</li></ol><figure class="shot" style="--w:760px;"><img src="'+o+'" alt="Nastavení stavby s tlačítkem Ukončit stavbu a stavem Probíhá" loading="lazy"></figure><p>Stavbu smí ukončit ten, kdo má na stavbě kompetenci <strong>Ukončení stavby</strong> – viz <a href="/buildary-help-preview/diary/userpermissions">Kdo co smí v deníku</a>.</p><h2 id="archivovat-nebo-smazat" tabindex="-1">Archivovat, nebo smazat <a class="header-anchor" href="#archivovat-nebo-smazat" aria-label="Permalink to &quot;Archivovat, nebo smazat&quot;">​</a></h2><figure class="shot" style="--w:580px;"><img src="'+d+'" alt="Okno Archivovat nebo smazat s výpočtem ceny za archivaci" loading="lazy"></figure><table tabindex="0"><thead><tr><th></th><th>Archivovat</th><th>Ke smazání</th></tr></thead><tbody><tr><td>Stav stavby</td><td><strong>Archivováno</strong></td><td><strong>Ke smazání</strong></td></tr><tr><td>Jak dlouho jsou data dostupná</td><td>10 let od ukončení stavby</td><td>30 dní od ukončení stavby, pak se stavba automaticky smaže</td></tr><tr><td>Co s daty</td><td>Všichni členové projektového týmu je mohou číst</td><td>Do smazání si je stáhněte na vlastní úložiště</td></tr><tr><td>Platba</td><td>Zálohový list na archivaci podle objemu dat a počtu let; částku ukáže okno před potvrzením</td><td>–</td></tr></tbody></table><p>V obou případech stavba přejde do režimu jen pro čtení: data můžete prohlížet a exportovat, ale ne měnit ani přidávat. Nový stav se zobrazí v Nastavení stavby u informací o stavbě.</p><div class="danger custom-block"><p class="custom-block-title">Rozhodnutí je nevratné</p><p>Jakmile zvolíte <strong>Archivovat</strong> nebo <strong>Ke smazání</strong>, volbu už nezměníte a stavbu nevrátíte do běžného provozu.</p></div><div class="tip custom-block"><p class="custom-block-title">Než stavbu dáte ke smazání</p><p>Stáhněte si deníky a další data, která si chcete ponechat – viz <a href="/buildary-help-preview/diary/download">Tisk a export deníku</a>. Po smazání stavby už je nezískáte.</p></div><h2 id="ukonceni-a-fakturace" tabindex="-1">Ukončení a fakturace <a class="header-anchor" href="#ukonceni-a-fakturace" aria-label="Permalink to &quot;Ukončení a fakturace&quot;">​</a></h2><p>Fakturují se jen aktivní stavby, takže ukončením skončí běžná fakturace za stavbu – viz <a href="/buildary-help-preview/firstofall/payment#ukoncit-fakturaci-za-stavbu">Ukončit fakturaci za stavbu</a>. Doklady za archivaci najdete s ostatními doklady domény na záložce <strong>Fakturace za doménu</strong>.</p><p>Stavba se může ukončit i sama: když výzva k platbě zůstane dva měsíce po splatnosti neuhrazená, stavba se ukončí ke smazání. Po úhradě do 3 měsíců od ukončení se vrátí do aktivního stavu – viz <a href="/buildary-help-preview/firstofall/payment#splatnost-a-neuhrazene-faktury">Splatnost a neuhrazené faktury</a>.</p><h2 id="kdo-se-o-ukonceni-dozvi" tabindex="-1">Kdo se o ukončení dozví <a class="header-anchor" href="#kdo-se-o-ukonceni-dozvi" aria-label="Permalink to &quot;Kdo se o ukončení dozví&quot;">​</a></h2><p>E-mail o ukončení stavby dostanou členové projektového týmu, kteří mají u <strong>E-mailového oznámení - Ukončení stavby</strong> nastaveno <strong>HTML email</strong> – viz <a href="/buildary-help-preview/diary/projectteam#e-mailova-oznameni">Projektový tým: firmy a lidé</a>.</p>',15)])])}const y=n(v,[["render",l]]);export{z as __pageData,y as default};
